import{_ as t,o as a,c as r,ag as l}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"对法不执","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-对法不执.md","filePath":"10-核心模型/model-对法不执.md","lastUpdated":1778155802000}'),e={name:"10-核心模型/model-对法不执.md"};function i(u,o,s,n,q,h){return a(),r("div",null,[...o[0]||(o[0]=[l(`<h1 id="对法不执" tabindex="-1">对法不执 <a class="header-anchor" href="#对法不执" aria-label="Permalink to &quot;对法不执&quot;">​</a></h1><blockquote><p>了空居士智慧体系第二心法。 连佛法都要放下，何况世间法。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>对法不执</strong> 是清净心的必然延伸。对境不住是&quot;不执着于现象&quot;，对法不执更进一步——<strong>不执着于任何东西，包括&quot;不执着&quot;本身，包括佛法本身</strong>。</p><h3 id="与相邻模型的边界" tabindex="-1">与相邻模型的边界 <a class="header-anchor" href="#与相邻模型的边界" aria-label="Permalink to &quot;与相邻模型的边界&quot;">​</a></h3><ul><li><strong>vs <a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a></strong>：对境不住是&quot;对外面发生的事不动心&quot;，对法不执是&quot;对学到的方法、修行的成果不执着&quot;。一个是外境的，一个是方法的。</li><li><strong>vs <a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a></strong>：对法不执是心法（放下对固定方法的执着），自然务实是方法论（实事求是、不照搬教条）——不执才能灵活，灵活才能务实。</li><li><strong>vs <a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a></strong>：不执一法才能走中道，执着一法必落边见。对法不执是圆融中和的心态前提。</li><li><strong>关键澄清</strong>：对法不执 ≠ 不修行。<strong>放下对方法的执着，不是放弃方法本身。</strong> 病没好药不能停，病好了药才放下。不修是惰性，不是不执。</li></ul><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><p>13个原子（从18个原始原子合并重复项后）分为<strong>6组</strong>，每组聚焦一个侧面：</p><hr><h3 id="一、法无定法-方法的非固定性" tabindex="-1">一、法无定法 | 方法的非固定性 <a class="header-anchor" href="#一、法无定法-方法的非固定性" aria-label="Permalink to &quot;一、法无定法 | 方法的非固定性&quot;">​</a></h3><blockquote><p>核心：没有一个固定的方法叫做&quot;开悟&quot;，因病与药，药随病去。</p></blockquote><h4 id="_1-法无定法" tabindex="-1">1. 法无定法 <a class="header-anchor" href="#_1-法无定法" aria-label="Permalink to &quot;1. 法无定法&quot;">​</a></h4><p><strong>原文</strong>：无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说。/ 没有固定的法门，各人因缘不同。</p><p><strong>解读</strong>：没有一个固定的方法叫做&quot;开悟&quot;，佛祖讲经是针对具体的人具体的问题，&quot;不可取，不可说&quot;。每个人的根器不同，最适合的方法也不同——不要拿自己的法门去评判别人，也不能照搬硬套。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无有定法">金刚经7分-无有定法</a></p></blockquote><h4 id="_2-无法可得" tabindex="-1">2. 无法可得 <a class="header-anchor" href="#_2-无法可得" aria-label="Permalink to &quot;2. 无法可得&quot;">​</a></h4><p><strong>原文</strong>：我于阿耨多罗三藐三菩提，乃至无有少法可得，是名阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：真正的开悟不是一个&quot;得到&quot;的过程，而是彻底明白&quot;无可得&quot;。连戒律都没有一个绝对标准——不杀生戒：我们呼吸就在杀死微生物，只能从整体观上做到不故意杀害。方法是对症下药，病好了药就不必再吃。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经22分-无法可得">金刚经22分-无法可得</a></p></blockquote><hr><h3 id="二、法门平等-不分别高下" tabindex="-1">二、法门平等 | 不分别高下 <a class="header-anchor" href="#二、法门平等-不分别高下" aria-label="Permalink to &quot;二、法门平等 | 不分别高下&quot;">​</a></h3><blockquote><p>核心：万法在果上平等，方法有快慢——不以局部方法否定全局效果。</p></blockquote><h4 id="_3-万法平等在果" tabindex="-1">3. 万法平等在果 <a class="header-anchor" href="#_3-万法平等在果" aria-label="Permalink to &quot;3. 万法平等在果&quot;">​</a></h4><p><strong>原文</strong>：万法在结果上平等，方法有快慢。坐飞机和走路都能到北京。/ 是法平等，无有高下，是名阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：不同的法门没有高下之分，都是到北京的方式。你坐飞机我不轻视走路的人，走路的人也不要笑话我贪图方便。平等是指心态上不分别高下，不是事相上没有区别——吃饭不能塞进眼睛里，这是智慧，不是不分别。不要用自己的法门评判别人的，格局放大，不以局部方法否定全局效果。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-万法平等在果">答疑2014-万法平等在果</a>、<a href="/liaokongjushi-wisdom/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p></blockquote><h4 id="_4-一切法皆是佛法" tabindex="-1">4. 一切法皆是佛法 <a class="header-anchor" href="#_4-一切法皆是佛法" aria-label="Permalink to &quot;4. 一切法皆是佛法&quot;">​</a></h4><p><strong>原文</strong>：一切法皆是佛法。</p><p><strong>解读</strong>：不是说做好事和做坏事没有区别，而是说只要不执着，一切现象都能成为觉悟的契机。小偷在偷东西时的恐惧和后悔，也可能让他觉醒。关键不在于法本身，在于你用什么样的心去面对。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a></p></blockquote><hr><h3 id="三、无所得-不贪果位" tabindex="-1">三、无所得 | 不贪果位 <a class="header-anchor" href="#三、无所得-不贪果位" aria-label="Permalink to &quot;三、无所得 | 不贪果位&quot;">​</a></h3><blockquote><p>核心：不觉得自己证得了什么，才是真正的证得。</p></blockquote><h4 id="_5-于法实无所得" tabindex="-1">5. 于法实无所得 <a class="header-anchor" href="#_5-于法实无所得" aria-label="Permalink to &quot;5. 于法实无所得&quot;">​</a></h4><p><strong>原文</strong>：如来在燃灯佛所，于法实无所得。/ 实无有法名阿罗汉——若阿罗汉作是念&quot;我得阿罗汉道&quot;，即著我人众生寿者。</p><p><strong>解读</strong>：真正的开悟不是得了什么法，而是明白&quot;无法可得&quot;。修行不是为了&quot;得到&quot;一个果位，而是放下一切执着——不觉得自己证得了什么，才是真正的证得。如果有一个法门让你执着，那还不是最究竟的。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a>、<a href="/liaokongjushi-wisdom/60-原文段落/金刚经9分-离欲与一相无相">金刚经9分-离欲与一相无相</a></p></blockquote><h4 id="_6-即得不等于得后" tabindex="-1">6. 即得不等于得后 <a class="header-anchor" href="#_6-即得不等于得后" aria-label="Permalink to &quot;6. 即得不等于得后&quot;">​</a></h4><p><strong>原文</strong>：以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：不是你修完善法之后才&quot;得&quot;到阿耨多罗三藐三菩提，而是你在修善法的同时，那个状态本身就是阿耨多罗三藐三菩提。一念相应一念佛，不是先修后得，是当下即是。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p></blockquote><h4 id="_7-通达无我法" tabindex="-1">7. 通达无我法 <a class="header-anchor" href="#_7-通达无我法" aria-label="Permalink to &quot;7. 通达无我法&quot;">​</a></h4><p><strong>原文</strong>：若菩萨通达无我法者，如来说名真是菩萨。</p><p><strong>解读</strong>：通达无我法，就是知道一切都是缘起性空，做一切事都是发自内心的自然流露，不图功德相。但也不是什么都不做——不做事是惰性，不是通达。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a></p></blockquote><hr><h3 id="四、不执功德相-做事不留痕迹" tabindex="-1">四、不执功德相 | 做事不留痕迹 <a class="header-anchor" href="#四、不执功德相-做事不留痕迹" aria-label="Permalink to &quot;四、不执功德相 | 做事不留痕迹&quot;">​</a></h3><blockquote><p>核心：做了但不觉得&quot;我在做&quot;，帮了就放下。</p></blockquote><h4 id="_8-不执功德相" tabindex="-1">8. 不执功德相 <a class="header-anchor" href="#_8-不执功德相" aria-label="Permalink to &quot;8. 不执功德相&quot;">​</a></h4><p><strong>原文</strong>：庄严佛土者，即非庄严，是名庄严。</p><p><strong>解读</strong>：做了一件好事，心里没有&quot;我在做好事&quot;的念头。做好事是自然的流露，不是求功德。雷锋帮助别人，帮完就走了，没有觉得了不起。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><h4 id="_9-度而无度" tabindex="-1">9. 度而无度 <a class="header-anchor" href="#_9-度而无度" aria-label="Permalink to &quot;9. 度而无度&quot;">​</a></h4><p><strong>原文</strong>：如是灭度无量无数无边众生，实无众生得灭度者。</p><p><strong>解读</strong>：发愿度一切众生，但心里不觉得&quot;我度了多少人&quot;。度众生是分内之事，就像父母养小孩一样自然，不会天天盯着小孩说&quot;今天又长大了&quot;。做事不留功德相。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><h4 id="_10-以无我行善" tabindex="-1">10. 以无我行善 <a class="header-anchor" href="#_10-以无我行善" aria-label="Permalink to &quot;10. 以无我行善&quot;">​</a></h4><p><strong>原文</strong>：以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。/ 所谓佛法者，即非佛法。</p><p><strong>解读</strong>：不是先成佛再行善，而是行善的同时就符合了成佛的标准。佛祖说的种种方法是对症下药，药方不能通用。不要将佛祖对甲说的话拿去给乙用。真正的佛法不是固定套路，而是&quot;缘起性空&quot;这个总规律的灵活应用。只管去做，不要去想&quot;我什么时候能开悟&quot;。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a>、<a href="/liaokongjushi-wisdom/60-原文段落/金刚经8分-佛法即非佛法">金刚经8分-佛法即非佛法</a></p></blockquote><hr><h3 id="五、放下方法之船-过了河要舍船" tabindex="-1">五、放下方法之船 | 过了河要舍船 <a class="header-anchor" href="#五、放下方法之船-过了河要舍船" aria-label="Permalink to &quot;五、放下方法之船 | 过了河要舍船&quot;">​</a></h3><blockquote><p>核心：法是指南针，不是终点——连佛法本身都要放下，何况世间的执着。</p></blockquote><h4 id="_11-法尚应舍" tabindex="-1">11. 法尚应舍 <a class="header-anchor" href="#_11-法尚应舍" aria-label="Permalink to &quot;11. 法尚应舍&quot;">​</a></h4><p><strong>原文</strong>：法尚应舍，何况非法。/ 是故不应取法，不应取非法。</p><p><strong>解读</strong>：连佛法本身都要放下，何况那些不是法的东西。法是指南针，不是终点——过了河，就要放下船。不能执着于方法（有），也不能执着于&quot;一切都是空的&quot;（空）。正如同吃药——病好了药就不必再吃，但病没好也不能不吃。不走两边，走中道。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></p></blockquote><h4 id="_12-不执形式" tabindex="-1">12. 不执形式 <a class="header-anchor" href="#_12-不执形式" aria-label="Permalink to &quot;12. 不执形式&quot;">​</a></h4><p><strong>原文</strong>：不要说须菩提一提问，佛赶快跑过去穿上袈裟来讲…就没有这种执着。</p><p><strong>解读</strong>：形式和仪式有它们的意义，但不要被形式绑住。清净心流露出来的是智慧，不需要刻意穿什么衣服来证明。佛祖对须菩提提问，没有说&quot;等一下我去穿袈裟&quot;，直接就说——这就是对法不执的示现。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-不执形式">金刚经1分-不执形式</a></p></blockquote><hr><h3 id="六、信心不逆-不执的知行合一" tabindex="-1">六、信心不逆 | 不执的知行合一 <a class="header-anchor" href="#六、信心不逆-不执的知行合一" aria-label="Permalink to &quot;六、信心不逆 | 不执的知行合一&quot;">​</a></h3><blockquote><p>核心：真正相信&quot;不执&quot;的道理并且开始落实，才是真信。</p></blockquote><h4 id="_13-信心不逆" tabindex="-1">13. 信心不逆 <a class="header-anchor" href="#_13-信心不逆" aria-label="Permalink to &quot;13. 信心不逆&quot;">​</a></h4><p><strong>原文</strong>：若复有人闻此经典，信心不逆，其福胜彼。</p><p><strong>解读</strong>：信心不逆就是真正相信并开始落实，不是嘴上说信。相信了《金刚经》的道理，在做事时就会自觉&quot;以无我无人修一切善法&quot;。知行合一才是真信——对法不执不是知道了就行，要落实在行动中才叫&quot;信心不逆&quot;。</p><blockquote><p>完整原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经15分-信心不逆">金刚经15分-信心不逆</a></p></blockquote><h4 id="_14-真信的检验" tabindex="-1">14. 真信的检验 <a class="header-anchor" href="#_14-真信的检验" aria-label="Permalink to &quot;14. 真信的检验&quot;">​</a></h4><p><strong>原文</strong>：信心不逆不是&quot;我信了&quot;三个字，是行为上自然流露。</p><p><strong>解读</strong>：真信有三层检验——（1）<strong>行为检验</strong>：做事的出发点变了没？是不带私心地帮人，还是帮的时候在想&quot;这能积功德&quot;？（2）<strong>反应检验</strong>：被人否定修行方法时，第一反应是辩护还是客观地听？（3）<strong>自然度检验</strong>：做好事还需要&quot;提醒自己&quot;吗？如果每次帮人都需要&quot;老师说过该做好事&quot;，说明信还没内化。真信的表现是——做了但不觉得&quot;我在做&quot;，放下但不宣告&quot;我放下了&quot;。</p><h4 id="_15-信心动摇时怎么办" tabindex="-1">15. 信心动摇时怎么办 <a class="header-anchor" href="#_15-信心动摇时怎么办" aria-label="Permalink to &quot;15. 信心动摇时怎么办&quot;">​</a></h4><p><strong>原文</strong>：听到不认同的说法，先别急着排斥，客观分析有没有可取之处。</p><p><strong>解读</strong>：信心不逆不等于固执。了空居士常说&quot;我的说法不对你可以不相信&quot;，真信不怕质疑。动摇往往是因为把&quot;法&quot;当成了&quot;我的法&quot;，把方法的有效性当成了自我认同——&quot;我的法门被否定=我被否定&quot;。实则法无定法，别人说你方法不对，可能正是提醒你别执着。动摇时回到原点：<strong>你信的是&quot;不执&quot;这个道理，不是信&quot;我的方法最好&quot;。</strong></p><hr><h2 id="常见失败诊断" tabindex="-1">常见失败诊断 <a class="header-anchor" href="#常见失败诊断" aria-label="Permalink to &quot;常见失败诊断&quot;">​</a></h2><p>了空居士在答疑中经常纠正学人在对法不执上的典型错误：</p><table tabindex="0"><thead><tr><th>错误状态</th><th>表现</th><th>为什么不是对法不执</th></tr></thead><tbody><tr><td><strong>借口型</strong></td><td>&quot;反正法无定法，怎么都行&quot;</td><td>拿法无定法当不作为的借口。不是不执，是不负责任——连基本的行善、修行都省了</td></tr><tr><td><strong>傲慢型</strong></td><td>&quot;我的法门最好，你们的不行&quot;</td><td>嘴上说万法平等，心里在分别高下。用自己学的方法去评判别人的方法，格局小了</td></tr><tr><td><strong>空谈型</strong></td><td>&quot;道理我都懂了，不用修了&quot;</td><td>把&quot;不执&quot;当成放弃修行的理由，落断灭见。法尚应舍≠现在就不用法</td></tr><tr><td><strong>宣告型</strong></td><td>&quot;我已经放下了&quot;反复挂在嘴边</td><td>真放下不需要宣告。嘴上说放下的时候，心里还在抓着那个&quot;我已经放下&quot;的成就感</td></tr><tr><td><strong>虚无型</strong></td><td>&quot;一切法皆是佛法，做好事做坏事没区别&quot;</td><td>混淆了&quot;不执&quot;和&quot;无分别心&quot;。整体观下，善恶对大众有客观标准——害人的法绝不是佛法</td></tr></tbody></table><hr><h2 id="操作方法-觉察→反问→放下" tabindex="-1">操作方法：觉察→反问→放下 <a class="header-anchor" href="#操作方法-觉察→反问→放下" aria-label="Permalink to &quot;操作方法：觉察→反问→放下&quot;">​</a></h2><p>当你发现自己执着于某个方法、境界、功德相时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执着升起（&quot;我的方法才对&quot;&quot;我修得不错&quot;&quot;什么时候才开悟&quot;）→</span></span>
<span class="line"><span>  第一步 觉察 → 知道&quot;我在执着于法&quot;（对&quot;执着&quot;本身也不怕念起）</span></span>
<span class="line"><span>  第二步 反问 → &quot;这个执着本身，是不是也要放下？&quot;</span></span>
<span class="line"><span>                &quot;病好了吗？没好的话药继续吃，但别把药当饭吃&quot;</span></span>
<span class="line"><span>  第三步 放下 → 回到当下该做的事——该念佛就念佛，该助人就助人</span></span>
<span class="line"><span>                不留恋&quot;我刚才想通了&quot;，继续往前走</span></span></code></pre></div><p><strong>操作手柄</strong>：对法不执的抓手是 <strong>&quot;反问执着本身&quot;</strong>——不是去判断&quot;这个方法对不对&quot;，而是问自己&quot;我抓着它不放，这本身是不是执着？&quot; 如同 <a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> 用理智暂停情绪，这里用 <strong>反问</strong> 暂停对法的抓取。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><h3 id="初阶-在日常小事中练-不执" tabindex="-1">初阶：在日常小事中练&quot;不执&quot; <a class="header-anchor" href="#初阶-在日常小事中练-不执" aria-label="Permalink to &quot;初阶：在日常小事中练&quot;不执&quot;&quot;">​</a></h3><ul><li>做了一件好事，告诉自己&quot;做了就过了&quot;，不在脑中反复回放&quot;我做了好事&quot;</li><li>帮了人，对方没说谢谢——觉察&quot;我在期待感谢&quot;的念头，然后放下</li><li>被人质疑修行方法时，先不急着辩护——对方的质疑也许有用，也许没用，看看再说</li><li>每天睡前回想一次：今天我有没有觉得&quot;我比你懂&quot;？（哪怕只有一瞬间）</li></ul><h3 id="中阶-在修行中放下对成果的抓取" tabindex="-1">中阶：在修行中放下对成果的抓取 <a class="header-anchor" href="#中阶-在修行中放下对成果的抓取" aria-label="Permalink to &quot;中阶：在修行中放下对成果的抓取&quot;">​</a></h3><ul><li>每天该念佛就念佛，该静坐就静坐，但不执着&quot;一定要达到什么境界&quot;</li><li>学到的方法，用得上就好好用，用不上就放下——不因为&quot;这是大师说的&quot;就硬套</li><li>发现自己和别人比较修行进度时，提醒自己：比较也是执着</li><li>当下的好心态就是修行成果，不是以后再得个&quot;果位&quot;</li><li>不拿别人的修行方法来评判自己，也不拿自己的标准去要求别人</li></ul><h3 id="高阶-连-不执-也不执" tabindex="-1">高阶：连&quot;不执&quot;也不执 <a class="header-anchor" href="#高阶-连-不执-也不执" aria-label="Permalink to &quot;高阶：连&quot;不执&quot;也不执&quot;">​</a></h3><ul><li>不用反复检查&quot;我执着了没有&quot;——检查本身又成了新的执着</li><li>做事自然流露，不贴&quot;我在修对法不执&quot;的标签</li><li>如同吃饭睡觉，方法融入本能——不是&quot;我在用法&quot;，是&quot;我就是这么做的&quot;</li></ul><h3 id="检验标准-你怎么知道自己进步了" tabindex="-1">检验标准（你怎么知道自己进步了） <a class="header-anchor" href="#检验标准-你怎么知道自己进步了" aria-label="Permalink to &quot;检验标准（你怎么知道自己进步了）&quot;">​</a></h3><ul><li><strong>初阶标志</strong>：别人质疑你的方法时，能不生气，先听对方说什么</li><li><strong>中阶标志</strong>：能自然地赞叹别人的法门好，心里没有&quot;但我的更好&quot;的对照</li><li><strong>高阶标志</strong>：法已经成为本能——做了好事心里不留痕迹，不是&quot;故意&quot;不留，是自然如此</li></ul><h3 id="预防和补救" tabindex="-1">预防和补救 <a class="header-anchor" href="#预防和补救" aria-label="Permalink to &quot;预防和补救&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>预防（平常时）</th><th>补救（执着升起后）</th></tr></thead><tbody><tr><td><strong>练什么</strong></td><td>万法平等在果、法无定法——日常小事中练&quot;不坚持我的方法最好&quot;</td><td>反问执着本身——觉察到&quot;我在抓着不放&quot;的那一刻就是转机</td></tr><tr><td><strong>怎么做</strong></td><td>每天刻意用一次别人的方式来做事（哪怕只是洗碗的顺序），体会&quot;不同方法也能到达&quot;</td><td>不因为&quot;我又执着了&quot;而自我谴责，直接反问&quot;这个执着能放下吗？&quot;</td></tr><tr><td><strong>检验</strong></td><td>能用三种以上方法达到同一件事，不觉得某一种&quot;才是对的&quot;</td><td>执着升起后能在几次反问内松开，不陷入&quot;放下→又抓起来→再放下&quot;的循环</td></tr></tbody></table><blockquote><p><strong>&gt; 用 <a href="/liaokongjushi-wisdom/meta-整体观">整体观</a></strong>：万法平等在果，格局放大——坐飞机和走路都能到北京，<strong>不以局部方法否定全局效果</strong>，不以自己的法门评判别人的。跳出自己的修行体系，从众生的整体利益看方法的对错。</p></blockquote><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — 对法不执是对境不住的深化：对外境不动心→对方法也不执着</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 不执一法才能走中道，执着一法必落边见</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 放下对固定方法的执着，才能实事求是、不照搬教条</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心</a> — 对法不执的道理，只有在真实处境中才能检验——被人否定方法时不辩解，才是真不执</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-天人合一">天人合一</a> — 万物一体的世界观是万法平等的基础：现象有别，本体统一</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会因由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第6分（正信希有分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>金刚经第10分（庄严净土分）</li><li>金刚经第11分（无为福胜分）</li><li>金刚经第15分（持经功德分）</li><li>金刚经第16分（能净业障分）</li><li>金刚经第17分（究竟无我分）</li><li>金刚经第19分（法界通化分）</li><li>金刚经第22分（无法可得分）</li><li>金刚经第23分（净心行善分）</li><li>金刚经第25分（化无所化分）</li><li>金刚经第27分（无断无灭分）</li><li>金刚经第32分（应化非真分）</li><li>答疑专辑2014/2019</li></ul><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a> 蒸馏日期：2026-05-05（第一版）2026-05-06（修订，新增是法平等无有高下，共18原子→13原子）2026-05-07（修订，新增边界声明、失败诊断表、操作方法、扩展第六组+2原子、分阶实践指引、预防补救表、补全模型链接）</p></blockquote>`,114)])])}const g=t(e,[["render",i]]);export{p as __pageData,g as default};
